import React, { useState, useEffect, useRef } from "react";


const Wheel = ({onFinished}) => {
  const sectors = [
    { color: "#4CAF50", label: "25%" },
    { color: "#2196F3", label: "10%" },
    { color: "#dc3545", label: "0%" },
    { color: "#2196F3", label: "2%" },
    { color: "#dc3545", label: "5%" },
    { color: "#4CAF50", label: "15%" },
    { color: "#2196F3", label: "0%" },
  ];

  const tot = sectors.length;
  const dia = 300;
  const rad = dia / 2;
  const arc = (2 * Math.PI) / tot;
  const angOffset = 2 * Math.PI * 0.75; // needle is north

  const [sectorIndex, setSectorIndex] = useState(0);
  const [spinAnimation, setSpinAnimation] = useState(null);
  const [ang, setAng] = useState(0);
  const [oldAng, setOldAng] = useState(0);
  const wheelRef = useRef(null);
  const spinRef = useRef(null);
  const animationFrameId = useRef(null);

  const rand = (m, M) => Math.random() * (M - m) + m;

  // Fix negative modulo
  const mod = (n, m) => (n % m + m) % m;

  const getIndex = (ang) => Math.floor(tot - mod(ang, 2 * Math.PI) / (2 * Math.PI) * tot) % tot;

  // Draw sector on the canvas
  const drawSector = (sector, i) => {
    const ang = arc * i;
    const ctx = wheelRef.current.getContext("2d");
  
    // Position the arrow just above the wheel (centered)
    const x = rad;
    const y = 0;
  
    ctx.save();  

    // ctx.save();
    // COLOR
    ctx.beginPath();
    ctx.fillStyle = sector.color;
    ctx.moveTo(rad, rad);
    ctx.arc(rad, rad, rad, ang, ang + arc);
    ctx.lineTo(rad, rad);
    ctx.fill();
    // TEXT
    ctx.translate(rad, rad);
    ctx.rotate(ang + arc / 2);
    ctx.textAlign = "right";
    ctx.fillStyle = "#fff";
    ctx.font = `bold ${26 * arc}px sans-serif`;
    ctx.fillText(sector.label, rad - 10, 10);
    ctx.restore();
  };


  const update = () => {
    const currentProgress = spinAnimation?.effect.getComputedTiming().progress ?? 0;
    const angDiff = ang - oldAng;
    const angCurr = angDiff * currentProgress;
    const angAbs = mod(oldAng + angCurr, 2 * Math.PI);

    const sectorIndexNew = getIndex(angAbs);
    if (sectorIndex !== sectorIndexNew) {
      // Sector changed! You can play a sound here
    }
    setSectorIndex(sectorIndexNew);
    if (spinRef.current) {
    //   spinRef.current.textContent = sectors[sectorIndex].label;
    //   spinRef.current.style.background = sectors[sectorIndex].color;
    }
  };

  const spin = (index, duration) => {
    index = tot - index;

    const angAbs = mod(ang, 2 * Math.PI);

    let angNew = arc * 2;
    angNew -= rand(0, arc);
    angNew = mod(angNew, 2 * Math.PI);

    const angDiff = mod(angNew - angAbs, 4 * Math.PI);

    const rev = 3 * Math.PI * Math.floor(rand(2, 4));

    setAng((prevAng) => prevAng + angDiff + rev);
    setOldAng(ang);

    const newSpinAnimation = wheelRef.current.animate([{ rotate: `17rad` }], {
      duration: 1000,
      easing: "cubic-bezier(0.2, 0, 0.1, 1)",
      fill: "forwards",
    });

    setSpinAnimation(newSpinAnimation);

    newSpinAnimation.addEventListener(
      "finish",
      () => {

      },
      { once: false }
    );
  };

  useEffect(() => {
    sectors.forEach(drawSector);
    update();
  }, [sectors]);

  const startSpin = () => {
    if (spinAnimation) return;
    // const serverIndex = +document.querySelector("select").value;
    spin(0, 500);

    setTimeout(()=> {
      setSpinAnimation(null);
      cancelAnimationFrame(animationFrameId.current);
      onFinished()
    }, 2000)
  };

  return (
    <div>
         <div
      style={{
        position: "relative",
          top: "52%", // Vertically center the arrow
          left: "50%", // Horizontally center the arrow
          transform: "translate(-50%, -50%)", 
        width: 0,
        height: 0,
        zIndex:700,
        borderLeft: "20px solid transparent",  // Makes the sides invisible
        borderRight: "20px solid transparent", // Makes the sides invisible
        borderTop: "20px solid transparent",  // Optional: Can make a thicker arrowhead
        borderBottom: "40px solid black",  // This is the arrowhead part (adjust size)
      }}
    ></div>
      <canvas id="wheel" ref={wheelRef} width={dia} height={dia} />
      <button className="buy-button" onClick={startSpin}>
        Γύρνα
      </button>
      <div ref={spinRef}>
      </div>
    </div>
  );
};

export default Wheel;
