import { Fragment, useEffect, useState } from "react";
import { ENDPOINTS } from '../app/config/config.js';
import { useAuth } from "../hooks/useAuth";
import { useDispatch, useSelector } from 'react-redux';
import Section from "../components/Section";
import SliderHome from "../components/Slider";
import { setReviews} from '../app/features/reviews_discount.slice.js';
import Wheel from "../components/wheel.js";
import PopupDialog from "../components/popupdialog.jsx";
import trackEvent from "../utils/trackEvent.js";

import useWindowScrollToTop from "../hooks/useWindowScrollToTop";
const Home = () => {
  const { user } = useAuth();
  console.log(user)
  const dispatch = useDispatch();
  const [products, setProducts] = useState([]);
  const [wheelSpin, setSpinWHeel] = useState(true);

  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const openDialog = () => {
    setIsDialogOpen(true);
  };

  const closeDialog = () => {
    setIsDialogOpen(false);
    setSpinWHeel(false)
  };

  const spinWheel = () => {
    localStorage.setItem("wheelDiscount","set")
    openDialog()
  }


  const fetchProducts = async () => {
    try {
      const response = await fetch(`${ENDPOINTS.Products}/`);
      if (!response.ok) throw new Error('Failed to fetch reviews');
      const data = await response.json();
      setProducts(data)
    } catch (error) {
    } finally {
    }
  };

  let isGame = localStorage.getItem('appVersion') === "gamification";

  trackEvent("navigated_to_home")

  const fetchUserReviews = async () => {
    try {
      
      const response = await fetch(`${ENDPOINTS.CommentReview}/reviews/getReviews/ofUser/`+ user.username);
      if (!response.ok) throw new Error('Failed to fetch reviews');
      const data = await response.json();
      dispatch(setReviews(data))
    } catch (error) {
    } finally {
    }
  };
  useEffect(() => {
    fetchUserReviews();
  }, []); //
  useEffect(() => {
    fetchProducts();
  }, []); //

  localStorage.getItem("gamification")
  console.log("Q12345",localStorage.getItem("gamification") )
  // const bestSales = products.filter((item) => item.category === "sofa");
  useWindowScrollToTop();
  return (
    <Fragment>

{isGame && wheelSpin && user === null &&
                    <h1 className="text-title" >
Γύρνα τον τροχό για να κερδίσεις σπουδαία δώρα</h1>
     
      }

      {isGame && wheelSpin && user === null &&
      <div className="wheel" >
         <Wheel onFinished={()=> spinWheel()} />
      </div>
     
      }

<PopupDialog
        isOpen={isDialogOpen}
        onClose={closeDialog}
        title="Συγχαρητήρια"
        message="Μόλις κερδισες 25% έκπτωση, κάνε εγγραφη για να την χρησιμοποιήσεις"
      />


      {isGame && <SliderHome />}
      <Section title={isGame? "Best Sales": ""} bgColor="#f6f9fc" productItems={products} />
    </Fragment>
  );
};

export default Home;
